import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const seenByOnError = async (reason: unknown): Promise<Error[]> => {
  const seen: Error[] = [];
  const failing = {
    sendMessage: () => ({[Symbol.asyncIterator]: () => ({next: () => Promise.reject(reason)})}),
  } as unknown as AIProvider & {sendMessage: () => AsyncIterable<MessageChunk>};
  const turn: ChatSession = {
    sessionId: 's',
    userId: 'u',
    entries: [{role: 'user', content: 'hi', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const orchestrator = createChatOrchestrator(failing, new PromptBuilder({identity: 'x'}), undefined, {
    hooks: {
      onError: async (_session, error) => {
        seen.push(error);
      },
    },
  });
  await orchestrator.processMessage(turn).catch(() => undefined);
  return seen;
};

describe('ChatOrchestrator onError cause', () => {
  it.each([['string boom'], [{code: 503}], [undefined]])(
    'wraps a non-Error rejection %p once, keeping it as the cause',
    async reason => {
      const seen = await seenByOnError(reason);

      expect(seen.map(error => ({isError: error instanceof Error, cause: error.cause}))).toEqual([
        {isError: true, cause: reason},
      ]);
    }
  );

  it('passes an Error through as the same instance', async () => {
    const original = new Error('boom');

    expect((await seenByOnError(original)).map(error => error === original)).toEqual([true]);
  });
});
EOF
